static const CoroIntrinsicNameAttrs &
getCoroIntrinsicNameAttrs(mlir::MLIRContext *ctx) {
  static thread_local llvm::DenseMap<mlir::MLIRContext *, CoroIntrinsicNameAttrs> cache;
  auto &names = cache[ctx];
  if (!names.coroAlloc) {
    names.coroAlloc = mlir::StringAttr::get(ctx, "llvm.coro.alloc");
    names.coroIsInRamp = mlir::StringAttr::get(ctx, "llvm.coro.is_in_ramp");
    names.coroNoop = mlir::StringAttr::get(ctx, "llvm.coro.noop");
    names.coroDestroy = mlir::StringAttr::get(ctx, "llvm.coro.destroy");
    names.coroDone = mlir::StringAttr::get(ctx, "llvm.coro.done");
    names.coroAwaitSuspendVoid =
        mlir::StringAttr::get(ctx, "llvm.coro.await.suspend.void");
    names.coroAwaitSuspendBool =
        mlir::StringAttr::get(ctx, "llvm.coro.await.suspend.bool");
    names.coroAwaitSuspendHandle =
        mlir::StringAttr::get(ctx, "llvm.coro.await.suspend.handle");
  }
  return names;
}

