/// Forward FP constraint discardable attributes from a CIR FP math op to the
/// lowered LLVM op. The convertOperation hook in LowerToLLVMIR.cpp will use
/// these to emit constrained FP intrinsics.
static void forwardFPConstraintsFromOp(mlir::Operation *srcOp,
                                       mlir::Operation *llvmOp) {
  if (auto fpExcept = srcOp->getAttr("cir.fp_exception"))
    llvmOp->setAttr("cir.fp_exception", fpExcept);
  if (auto roundMode = srcOp->getAttr("cir.rounding_mode"))
    llvmOp->setAttr("cir.rounding_mode", roundMode);
  if (auto callStrictFP = srcOp->getAttr("cir.call_strictfp"))
    llvmOp->setAttr("cir.call_strictfp", callStrictFP);
  if (auto callMemoryNone = srcOp->getAttr("cir.call_memory_none"))
    llvmOp->setAttr("cir.call_memory_none", callMemoryNone);
}

mlir::LogicalResult CIRToLLVMSqrtOpLowering::matchAndRewrite(
    cir::SqrtOp op, OpAdaptor adaptor,
    mlir::ConversionPatternRewriter &rewriter) const {
  mlir::Type resTy = typeConverter->convertType(op.getType());
  auto fmf = mlir::LLVM::FastmathFlagsAttr::get(
      op.getContext(), convertFastMathFlags(op.getFastMathFlags()));
  auto newOp = rewriter.replaceOpWithNewOp<mlir::LLVM::SqrtOp>(
      op, resTy, adaptor.getSrc(), fmf);
  forwardFPConstraintsFromOp(op, newOp);
  return mlir::success();
}

